- path: src/routes/README.md
  content: |
      # Routes

      TanStack Start uses **file-based routing**. Every `.tsx` file in this directory
      defines a route. Do **not** create `src/pages/`, `src/routes/_app/index.tsx`, or
      `app/layout.tsx` — those are Next.js / Remix conventions. The only root layout
      is `src/routes/__root.tsx`.

      ## Conventions

      | File | URL |
      | --- | --- |
      | `index.tsx` | `/` |
      | `about.tsx` | `/about` |
      | `users/index.tsx` | `/users` |
      | `users/$id.tsx` | `/users/:id` (dynamic — bare `$`, no curly braces) |
      | `posts/{-$category}.tsx` | `/posts/:category?` (optional segment) |
      | `files/$.tsx` | `/files/*` (splat — read via `_splat` param, never `*`) |
      | `_layout.tsx` | layout route (renders children via `<Outlet />`) |
      | `__root.tsx` | app shell — wraps every page; preserve `<Outlet />` |

      `routeTree.gen.ts` is auto-generated. Don't edit it by hand.

- path: src/routes/__root.tsx
  content: |
      import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
      import {
        Outlet,
        Link,
        createRootRouteWithContext,
        useRouter,
        HeadContent,
        Scripts,
        type ErrorComponentProps,
      } from "@tanstack/react-router";
      import { useEffect, type ReactNode } from "react";

      import appCss from "../styles.css?url";
      import { reportLovableError } from "../lib/lovable-error-reporting";

      function NotFoundComponent() {
        return (
          <div className="flex min-h-screen items-center justify-center bg-background px-4">
            <div className="max-w-md text-center">
              <h1 className="text-7xl font-bold text-foreground">404</h1>
              <h2 className="mt-4 text-xl font-semibold text-foreground">Page not found</h2>
              <p className="mt-2 text-sm text-muted-foreground">
                The page you're looking for doesn't exist or has been moved.
              </p>
              <div className="mt-6">
                <Link
                  to="/"
                  className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
                >
                  Go home
                </Link>
              </div>
            </div>
          </div>
        );
      }

      function ErrorComponent({ error, reset }: ErrorComponentProps) {
        console.error(error);
        const router = useRouter();
        useEffect(() => {
          reportLovableError(error, { boundary: "tanstack_root_error_component" });
        }, [error]);

        return (
          <div className="flex min-h-screen items-center justify-center bg-background px-4">
            <div className="max-w-md text-center">
              <h1 className="text-xl font-semibold tracking-tight text-foreground">
                This page didn't load
              </h1>
              <p className="mt-2 text-sm text-muted-foreground">
                Something went wrong on our end. You can try refreshing or head back home.
              </p>
              <div className="mt-6 flex flex-wrap justify-center gap-2">
                <button
                  onClick={() => {
                    router.invalidate();
                    reset();
                  }}
                  className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
                >
                  Try again
                </button>
                <a
                  href="/"
                  className="inline-flex items-center justify-center rounded-md border border-input bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent"
                >
                  Go home
                </a>
              </div>
            </div>
          </div>
        );
      }

      export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
        head: () => ({
          // Replace these placeholders with the app's name and description when first building the app.
          // Each content route, / included, must still set its own head(). Never add og:image or
          // twitter:image here: every page without its own would inherit the root's preview image.
          meta: [
            { charSet: "utf-8" },
            { name: "viewport", content: "width=device-width, initial-scale=1" },
            { title: "Kampung IT Solo" },
            {
              name: "description",
              content:
                "Pusat Eduwisata IT & Laboratorium Peradaban Digital di RT 06/RW 21 Surakarta, bagian dari Bin Alfan Group.",
            },
            { name: "author", content: "Kampung IT Solo" },
            { property: "og:title", content: "Kampung IT Solo" },
            {
              property: "og:description",
              content:
                "Pusat Eduwisata IT & Laboratorium Peradaban Digital di RT 06/RW 21 Surakarta, bagian dari Bin Alfan Group.",
            },
            { property: "og:type", content: "website" },
            { name: "twitter:card", content: "summary_large_image" },
          ],
          links: [
            {
              rel: "stylesheet",
              href: appCss,
            },
            { rel: "icon", href: "/kampung-it-solo.png", type: "image/png" },
            { rel: "apple-touch-icon", href: "/kampung-it-solo.png" },
            { rel: "preconnect", href: "https://fonts.googleapis.com" },
            { rel: "preconnect", href: "https://fonts.gstatic.com", crossOrigin: "anonymous" },
            {
              rel: "stylesheet",
              href: "https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap",
            },
          ],
        }),
        shellComponent: RootShell,
        component: RootComponent,
        notFoundComponent: NotFoundComponent,
        errorComponent: ErrorComponent,
      });

      function RootShell({ children }: { children: ReactNode }) {
        return (
          <html lang="id">
            <head>
              <HeadContent />
            </head>
            <body>
              {children}
              <Scripts />
            </body>
          </html>
        );
      }

      function RootComponent() {
        const { queryClient } = Route.useRouteContext();

        return (
          <QueryClientProvider client={queryClient}>
            {/* Required: nested routes render here. Removing <Outlet /> breaks all child routes. */}
            <Outlet />
          </QueryClientProvider>
        );
      }

- path: src/routes/index.tsx
  content: |
      import { createFileRoute } from "@tanstack/react-router";
      import { useEffect, useState } from "react";
      import { ArrowUp } from "lucide-react";
      import { Hero } from "@/components/landing/Hero";
      import { Ticker } from "@/components/landing/Ticker";
      import { About } from "@/components/landing/About";
      import { Ecosystem } from "@/components/landing/Ecosystem";
      import { Program } from "@/components/landing/Program";
      import { Impact } from "@/components/landing/Impact";
      import { Network } from "@/components/landing/Network";
      import { Faq } from "@/components/landing/Faq";
      import { Reservation } from "@/components/landing/Reservation";
      import { Cta } from "@/components/landing/Cta";
      import { Footer } from "@/components/landing/Footer";
      import { useScrollReveal } from "@/hooks/use-scroll-reveal";
      import { useScrollParallax } from "@/hooks/use-scroll-parallax";

      const SITE_URL = "https://kampungitsolo.com";

      // Structured data: identitas lembaga + situs, dipakai mesin pencari untuk memahami
      // entitas Kampung IT Solo dan menampilkan informasi kontak yang akurat.
      const STRUCTURED_DATA = {
        "@context": "https://schema.org",
        "@graph": [
          {
            "@type": "EducationalOrganization",
            "@id": `${SITE_URL}/#organization`,
            name: "Kampung IT Solo",
            alternateName: "Kampung IT Solo — Pusat Eduwisata IT",
            url: SITE_URL,
            logo: `${SITE_URL}/kampung-it-solo.png`,
            image: `${SITE_URL}/og-image.jpg`,
            description:
              "Pusat eduwisata IT dan laboratorium peradaban digital di RT 06/RW 21 Surakarta, bagian dari Bin Alfan Group.",
            email: "kampungitsolo@gmail.com",
            telephone: "+62-812-3566-6665",
            address: {
              "@type": "PostalAddress",
              streetAddress: "RT 06 / RW 21",
              addressLocality: "Surakarta",
              addressRegion: "Jawa Tengah",
              addressCountry: "ID",
            },
            areaServed: ["Surakarta", "Sukoharjo", "Solo Raya"],
            parentOrganization: { "@type": "Organization", name: "Bin Alfan Group" },
            sameAs: ["https://elfanaiacademy.com", "https://ufukhijau.com"],
          },
          {
            "@type": "WebSite",
            "@id": `${SITE_URL}/#website`,
            name: "Kampung IT Solo",
            url: SITE_URL,
            inLanguage: "id-ID",
            publisher: { "@id": `${SITE_URL}/#organization` },
          },
        ],
      };

      export const Route = createFileRoute("/")({
        head: () => ({
          meta: [
            {
              title: "Kampung IT Solo — Pusat Eduwisata IT & Lab Peradaban Digital",
            },
            {
              name: "description",
              content:
                "Pusat eduwisata IT & laboratorium peradaban digital di Surakarta. 10 produk teknologi, 16 modul Elfan System, serta program digital untuk desa, UMKM, dan pelajar.",
            },
            { name: "robots", content: "index, follow, max-image-preview:large" },
            {
              property: "og:title",
              content: "Kampung IT Solo — Lab. Peradaban Berbasis IT",
            },
            {
              property: "og:description",
              content:
                "Pusat Eduwisata IT dan Laboratorium Peradaban Digital di RT 06/RW 21 Surakarta, bagian dari Bin Alfan Group.",
            },
            { property: "og:type", content: "website" },
            { property: "og:url", content: SITE_URL },
            { property: "og:site_name", content: "Kampung IT Solo" },
            { property: "og:locale", content: "id_ID" },
            { property: "og:image", content: `${SITE_URL}/og-image.jpg` },
            { property: "og:image:width", content: "1200" },
            { property: "og:image:height", content: "630" },
            { property: "og:image:alt", content: "Kampung IT Solo — Pusat Eduwisata IT Surakarta" },
            { name: "twitter:card", content: "summary_large_image" },
            { name: "twitter:title", content: "Kampung IT Solo — Lab. Peradaban Berbasis IT" },
            {
              name: "twitter:description",
              content:
                "Pusat Eduwisata IT & Laboratorium Peradaban Digital di Surakarta — 10 produk teknologi dan 16 modul Elfan System.",
            },
            { name: "twitter:image", content: `${SITE_URL}/og-image.jpg` },
          ],
          links: [{ rel: "canonical", href: SITE_URL }],
        }),
        component: Index,
      });

      function BackToTop() {
        const [show, setShow] = useState(false);
        useEffect(() => {
          const onScroll = () => setShow(window.scrollY > 700);
          onScroll();
          window.addEventListener("scroll", onScroll, { passive: true });
          return () => window.removeEventListener("scroll", onScroll);
        }, []);
        return (
          <button
            type="button"
            aria-label="Kembali ke atas"
            onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
            className={`fixed bottom-6 right-6 z-50 grid size-11 place-items-center rounded-full bg-forest text-forest-foreground shadow-card transition-[opacity,translate] duration-300 hover:brightness-110 ${
              show ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-3 opacity-0"
            }`}
          >
            <ArrowUp className="size-5" />
          </button>
        );
      }

      function Index() {
        useScrollReveal();
        useScrollParallax();
        return (
          <main id="konten" tabIndex={-1} className="bg-background">
            <a
              href="#konten"
              className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-[70] focus:rounded-full focus:bg-navy focus:px-5 focus:py-3 focus:text-sm focus:font-bold focus:text-navy-foreground"
            >
              Langsung ke konten
            </a>
            <script
              type="application/ld+json"
              dangerouslySetInnerHTML={{ __html: JSON.stringify(STRUCTURED_DATA) }}
            />
            <Hero />
            <Ticker />
            <About />
            <Ecosystem />
            <Program />
            <Impact />
            <Network />
            <Faq />
            <Cta />
            <Reservation />
            <Footer />
            <BackToTop />
          </main>
        );
      }

- path: src/components/landing/Navbar.tsx
  content: |
      import { useEffect, useRef, useState } from "react";
      import { ArrowLeft, ArrowRight, Menu, MessageCircle, Search, X } from "lucide-react";
      import { Link } from "@tanstack/react-router";
      import { Button } from "@/components/ui/button";
      import { Logo } from "./Logo";
      import { SearchDialog } from "./SearchDialog";

      const links = [
        { label: "Beranda", href: "#beranda" },
        { label: "Tentang", href: "#tentang" },
        { label: "Ekosistem", href: "#ekosistem" },
        { label: "Program", href: "#program" },
        { label: "Dampak", href: "#dampak" },
        { label: "FAQ", href: "#faq" },
        { label: "Kolaborasi", href: "#kolaborasi" },
      ];

      type NavbarProps = {
        variant?: "landing" | "detail";
      };

      export function Navbar({ variant = "landing" }: NavbarProps) {
        const isDetail = variant === "detail";
        const [open, setOpen] = useState(false);
        const [scrolled, setScrolled] = useState(false);
        const [active, setActive] = useState("beranda");
        const [progress, setProgress] = useState(0);
        const [searchOpen, setSearchOpen] = useState(false);
        const headerRef = useRef<HTMLElement>(null);

        // Menu mobile menutup saat Escape ditekan atau klik di luar header.
        useEffect(() => {
          if (!open) return;
          const onKey = (e: KeyboardEvent) => {
            if (e.key === "Escape") setOpen(false);
          };
          const onPointer = (e: PointerEvent) => {
            if (!headerRef.current?.contains(e.target as Node)) setOpen(false);
          };
          document.addEventListener("keydown", onKey);
          document.addEventListener("pointerdown", onPointer);
          return () => {
            document.removeEventListener("keydown", onKey);
            document.removeEventListener("pointerdown", onPointer);
          };
        }, [open]);

        useEffect(() => {
          const onScroll = () => {
            setScrolled(window.scrollY > 40);
            const max = document.documentElement.scrollHeight - window.innerHeight;
            setProgress(max > 0 ? Math.min(1, window.scrollY / max) : 0);
            if (isDetail) return;

            // Sorot menu terakhir yang judul section-nya sudah melewati bawah navbar.
            const offset = 140;
            let current = "beranda";
            for (const l of links) {
              const id = l.href.slice(1);
              const el = document.getElementById(id);
              if (el && el.getBoundingClientRect().top <= offset) current = id;
            }
            setActive(current);
          };
          onScroll();
          window.addEventListener("scroll", onScroll, { passive: true });
          window.addEventListener("resize", onScroll);
          return () => {
            window.removeEventListener("scroll", onScroll);
            window.removeEventListener("resize", onScroll);
          };
        }, [isDetail]);

        return (
          <>
            <div className="h-20" aria-hidden="true" />
            {!isDetail && (
              <div
                aria-hidden="true"
                className="fixed inset-x-0 top-0 z-[60] h-[3px] origin-left bg-gradient-brand transition-transform duration-150 ease-out"
                style={{ transform: `scaleX(${progress})` }}
              />
            )}
            <header
              ref={headerRef}
              className={`fixed inset-x-0 top-0 z-50 transition-all duration-500 ${scrolled ? "px-3 pt-3 sm:px-6" : ""}`}
            >
              <div
                className={`mx-auto flex items-center justify-between transition-all duration-500 ease-out ${
                  scrolled
                    ? "h-16 max-w-6xl rounded-full border border-border/70 bg-background/85 px-4 shadow-card backdrop-blur-md lg:px-6"
                    : "h-20 max-w-[112rem] px-6 lg:px-12"
                }`}
              >
                <Logo href={isDetail ? "/" : "#beranda"} className={scrolled ? "h-10" : "h-14"} />

                {isDetail ? (
                  <div className="flex items-center gap-3">
                    <Link
                      to="/"
                      className="hidden items-center gap-1.5 text-[0.78rem] font-semibold text-ink transition-colors hover:text-forest sm:inline-flex"
                    >
                      <ArrowLeft className="size-4" /> Beranda
                    </Link>
                    <Button variant="forest" size="pillSm" asChild>
                      <a href="https://wa.me/6281235666665" target="_blank" rel="noreferrer">
                        Hubungi Kami <MessageCircle />
                      </a>
                    </Button>
                  </div>
                ) : (
                  <>
                    <nav aria-label="Navigasi utama" className="hidden items-center gap-7 lg:flex">
                      {links.map((l) => {
                        const isActive = l.href === `#${active}`;
                        return (
                          <a
                            key={l.label}
                            href={l.href}
                            aria-current={isActive ? "true" : undefined}
                            className={`group relative flex items-center gap-1 py-2 text-[0.8rem] transition-colors duration-300 hover:text-forest ${
                              isActive ? "font-bold text-navy" : "font-medium text-ink"
                            }`}
                          >
                            {l.label}
                            <span
                              aria-hidden="true"
                              className={`absolute -bottom-1.5 left-0 h-[3px] w-full origin-left rounded-full bg-forest transition-[scale] duration-300 ease-out ${
                                isActive ? "scale-x-100" : "scale-x-0 group-hover:scale-x-100"
                              }`}
                            />
                          </a>
                        );
                      })}
                    </nav>
                    <div className="hidden items-center gap-4 lg:flex">
                      <button
                        type="button"
                        aria-label="Cari"
                        onClick={() => setSearchOpen(true)}
                        className="grid size-10 place-items-center rounded-full border border-border bg-background text-navy transition-colors hover:bg-surface"
                      >
                        <Search className="size-4" />
                      </button>
                      <Button variant="forest" size="pill" asChild>
                        <a href="#reservasi">
                          Reservasi <ArrowRight />
                        </a>
                      </Button>
                    </div>
                    <div className="flex items-center gap-1 lg:hidden">
                      <button
                        type="button"
                        aria-label="Cari"
                        onClick={() => {
                          setOpen(false);
                          setSearchOpen(true);
                        }}
                        className="grid size-10 place-items-center rounded-full text-navy transition-colors hover:bg-surface"
                      >
                        <Search className="size-5" />
                      </button>
                      <button
                        type="button"
                        className="grid size-10 place-items-center rounded-full text-navy transition-colors hover:bg-surface"
                        aria-label={open ? "Tutup menu" : "Buka menu"}
                        aria-expanded={open}
                        aria-controls="mobile-menu"
                        onClick={() => setOpen(!open)}
                      >
                        {open ? <X /> : <Menu />}
                      </button>
                    </div>
                  </>
                )}
              </div>
              {!isDetail && (
                <div
                  id="mobile-menu"
                  inert={!open}
                  className={`absolute inset-x-0 origin-top border-y bg-background px-6 pb-5 pt-2 shadow-card transition-[opacity,translate,scale,visibility] duration-300 ease-out motion-reduce:transition-none lg:hidden ${
                    open
                      ? "visible translate-y-0 scale-y-100 opacity-100"
                      : "invisible -translate-y-2 scale-y-95 opacity-0"
                  } ${scrolled ? "top-[5.25rem] mx-3 rounded-2xl border-x sm:mx-6" : "top-20"}`}
                >
                  {links.map((l) => {
                    const isActive = l.href === `#${active}`;
                    return (
                      <a
                        key={l.label}
                        href={l.href}
                        onClick={() => setOpen(false)}
                        aria-current={isActive ? "true" : undefined}
                        className={`block py-2 text-sm ${
                          isActive ? "font-bold text-forest" : "font-semibold text-navy"
                        }`}
                      >
                        {l.label}
                      </a>
                    );
                  })}
                  <Button variant="forest" size="pill" className="mt-3 w-full" asChild>
                    <a href="#reservasi" onClick={() => setOpen(false)}>
                      Reservasi Kunjungan <ArrowRight />
                    </a>
                  </Button>
                </div>
              )}
            </header>
            {!isDetail && (
              <SearchDialog open={searchOpen} onOpenChange={setSearchOpen} sections={links} />
            )}
          </>
        );
      }

