- path: src/data/routes.ts
  content: |
      import { products } from "./products";

      export type ChangeFrequency = "daily" | "weekly" | "monthly" | "yearly";

      export type SiteRoute = {
        path: string;
        lastmod: string;
        changefreq: ChangeFrequency;
        priority: number;
      };

      const LAST_MODIFIED = "2026-11-23";

      const staticRoutes: SiteRoute[] = [
        { path: "/", lastmod: LAST_MODIFIED, changefreq: "weekly", priority: 1.0 },
        { path: "/products", lastmod: LAST_MODIFIED, changefreq: "weekly", priority: 0.9 },
        { path: "/tentang", lastmod: LAST_MODIFIED, changefreq: "monthly", priority: 0.7 },
        { path: "/kontak", lastmod: LAST_MODIFIED, changefreq: "monthly", priority: 0.7 },
        {
          path: "/kebijakan-privasi",
          lastmod: LAST_MODIFIED,
          changefreq: "yearly",
          priority: 0.3,
        },
        {
          path: "/syarat-ketentuan",
          lastmod: LAST_MODIFIED,
          changefreq: "yearly",
          priority: 0.3,
        },
      ];

      export const siteRoutes: SiteRoute[] = [
        ...staticRoutes,
        ...products.map((product) => ({
          path: `/products/${product.slug}`,
          lastmod: LAST_MODIFIED,
          changefreq: "monthly" as const,
          priority: 0.8,
        })),
      ];

- path: src/lib/seo.ts
  content: |
      import { canonicalUrl, DEFAULT_OG_IMAGE, SITE_NAME } from "./site";

      type PageHeadInput = {
        title: string;
        description: string;
        path: string;
        image?: string;
        type?: "website" | "article";
      };

      export function pageHead({
        title,
        description,
        path,
        image = DEFAULT_OG_IMAGE,
        type = "website",
      }: PageHeadInput) {
        const url = canonicalUrl(path);

        return {
          meta: [
            { title },
            { name: "description", content: description },
            { name: "robots", content: "index, follow, max-image-preview:large" },
            { property: "og:title", content: title },
            { property: "og:description", content: description },
            { property: "og:type", content: type },
            { property: "og:url", content: url },
            { property: "og:site_name", content: SITE_NAME },
            { property: "og:locale", content: "id_ID" },
            { property: "og:image", content: image },
            { property: "og:image:width", content: "1200" },
            { property: "og:image:height", content: "630" },
            { property: "og:image:alt", content: title },
            { name: "twitter:card", content: "summary_large_image" },
            { name: "twitter:title", content: title },
            { name: "twitter:description", content: description },
            { name: "twitter:image", content: image },
          ],
          links: [{ rel: "canonical", href: url }],
        };
      }

