      type ProductSearchEntry = {
        group: "Produk";
        label: string;
        description: string;
        slug: string;
        path: string;
        keywords: string[];
      };

      export type SearchEntry = PageSearchEntry | ProductSearchEntry;

      const pages: PageSearchEntry[] = [
        {
          group: "Halaman",
          label: "Beranda",
          description: "Ringkasan Kampung IT Solo, program, ekosistem, dan reservasi.",
          path: "/",
          keywords: ["kampung it solo", "eduwisata", "solo raya"],
        },
        {
          group: "Halaman",
