- path: src/test/app-routing.test.tsx
  content: |
      import { QueryClient } from "@tanstack/react-query";
      import { createRouter, rootRouteId } from "@tanstack/react-router";
      import { describe, expect, it } from "vitest";

      import { products } from "@/data/products";
      import { routeTree } from "@/routeTree.gen";

      // Match routes without running loaders or rendering: loaders may need a server or
      // network the test run lacks, and jsdom never loads the stylesheets React waits on.
      const publishedPaths = [
        "/",
        "/products",
        "/tentang",
        "/kontak",
        "/kebijakan-privasi",
        "/syarat-ketentuan",
        "/sitemap.xml",
        ...products.map((product) => `/products/${product.slug}`),
      ];

      describe("App routing", () => {
        it.each(publishedPaths)("matches a page for %s instead of falling back to not found", (path) => {
          const router = createRouter({ routeTree, context: { queryClient: new QueryClient() } });

          const matches = router.matchRoutes(path);

          expect(matches.at(-1)?.routeId).not.toBe(rootRouteId);
        });
      });

- path: src/test/site-data.test.ts
  content: |
      import { describe, expect, it } from "vitest";

      import { products } from "@/data/products";
      import { siteRoutes } from "@/data/routes";
      import { searchEntries } from "@/data/search";

      const publishedPaths = new Set(siteRoutes.map((route) => route.path));
      const unpublishedPrefixes = ["/program", "/eduwisata", "/cerita", "/artikel", "/untuk"];

      describe("Product data", () => {
        it("has ten products with unique slugs", () => {
          expect(products).toHaveLength(10);
          expect(new Set(products.map((product) => product.slug)).size).toBe(products.length);
        });

        it("marks exactly one catalog featured product", () => {
          const featured = products.filter((product) => product.catalogFeatured);
          expect(featured).toHaveLength(1);
          expect(featured[0]?.slug).toBe("elfan-system");
        });

        it("keeps required catalog fields filled", () => {
          for (const product of products) {
            expect(product.name.length).toBeGreaterThan(0);
            expect(product.category.length).toBeGreaterThan(0);
            expect(product.cardDesc.length).toBeGreaterThan(0);
            expect(product.summary.length).toBeGreaterThan(0);
            expect(product.image.length).toBeGreaterThan(0);
          }
        });
      });

      describe("Route manifest", () => {
        it("contains every published page and no duplicates", () => {
          expect(siteRoutes).toHaveLength(16);
          expect(new Set(siteRoutes.map((route) => route.path)).size).toBe(siteRoutes.length);
        });

        it("only contains Batch 1 routes", () => {
          for (const route of siteRoutes) {
            expect(route.path.startsWith("/")).toBe(true);
            expect(unpublishedPrefixes.some((prefix) => route.path.startsWith(prefix))).toBe(false);
          }
        });

        it("uses absolute-friendly paths without a trailing slash", () => {
          for (const route of siteRoutes) {
            if (route.path !== "/") expect(route.path.endsWith("/")).toBe(false);
          }
        });
      });

      describe("Search entries", () => {
        it("only points to published routes", () => {
          for (const entry of searchEntries) {
            expect(publishedPaths.has(entry.path)).toBe(true);
          }
        });

        it("includes all ten products", () => {
          const productEntries = searchEntries.filter((entry) => entry.group === "Produk");
          expect(productEntries).toHaveLength(10);
        });
      });

- path: src/test/sitemap.test.ts
  content: |
      import { describe, expect, it } from "vitest";

      import { siteRoutes } from "@/data/routes";
      import { renderSitemap } from "@/lib/sitemap";

      const xml = renderSitemap(siteRoutes);
      const locations = [...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map((match) => match[1] ?? "");

      describe("Sitemap", () => {
        it("renders XML with one URL per published route", () => {
          expect(xml.startsWith('<?xml version="1.0" encoding="UTF-8"?>')).toBe(true);
          expect((xml.match(/<url>/g) ?? []).length).toBe(siteRoutes.length);
          expect(locations).toHaveLength(siteRoutes.length);
        });

        it("has no duplicate URLs", () => {
          expect(new Set(locations).size).toBe(locations.length);
        });

        it("uses absolute HTTPS URLs", () => {
          for (const location of locations) {
            expect(location.startsWith("https://kampungitsolo.com")).toBe(true);
          }
        });

        it("does not include routes from later batches", () => {
          expect(xml).not.toContain("/program");
          expect(xml).not.toContain("/eduwisata");
          expect(xml).not.toContain("/cerita");
          expect(xml).not.toContain("/artikel");
          expect(xml).not.toContain("/untuk");
        });
      });

