export function fitDescription(text: string, suffix = "", max = 160) {
  const base = text.trim();
  const combined = suffix ? `${base} ${suffix.trim()}` : base;
  if (combined.length <= max) return combined;
  return `${combined.slice(0, max - 3).replace(/\s+\S*$/, "")}...`;
}

