set -o pipefail; bun -e '
const base="http://localhost:4174";
const paths=["/artikel","/artikel/kursus-coding-untuk-anak-di-solo","/artikel/ai-untuk-pesantren","/artikel/plts-untuk-sekolah","/artikel/digitalisasi-desa","/untuk","/untuk/sekolah","/untuk/desa","/untuk/umkm"];
const links=new Set(); let problems=[];
for(const p of paths){
 const r=await fetch(base+p); const html=await r.text();
 if(!html.includes("<h1")) problems.push(`${p}: no h1`);
 if(html.includes("href=\"#\"")) problems.push(`${p}: empty href`);
 if(html.includes("/untuk/pesantren")) problems.push(`${p}: pesantren link`);
 const ld=[...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)];
 if(ld.length===0) problems.push(`${p}: no jsonld`);
 for(const m of ld){try{JSON.parse(m[1]);}catch(e){problems.push(`${p}: bad jsonld`);}}
 for(const m of html.matchAll(/href="(\/[^"#?]*)"/g)) links.add(m[1]);
 if(p.startsWith("/artikel/")){
  if(!html.includes("Daftar isi")) problems.push(`${p}: no toc`);
  const ids=[...html.matchAll(/<h2 id="([^"]+)"/g)].map(m=>m[1]);
  if(ids.length<3) problems.push(`${p}: only ${ids.length} h2 ids`);
 }
}
let fail=0;
for(const l of links){const r=await fetch(base+l); if(r.status!==200){console.log("LINK FAIL",l,r.status); fail++;}}
console.log("pages",paths.length,"internal links",links.size,"link failures",fail);
console.log(problems.length?problems.join("\n"):"no html/jsonld problems");
'

